import{_ as p,a0 as u,w as a,s as o,ao as r,I as n,x as i,a1 as s,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"現代 Linux 的五大初始化系統（1992-2015） | LCTT x X-CMD","titleTemplate":false,"description":"現代 Linux 的五大初始化系統（1992-2015） | LCTT (201610) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"現代 Linux 的五大初始化系統（1992-2015） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"現代 Linux 的五大初始化系統（1992-2015） | LCTT (201610) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201610/20160811 5 best linux init system","title":"現代 Linux 的五大初始化系統（1992-2015）","tag":"201610","desc":""},"relativePath":"201610/20160811 5 best linux init system.md","filePath":"[post].md"}'),m={name:"201610/20160811 5 best linux init system.md"};function d(x,t,S,T,y,f){const l=u("Link");return a(),o("div",null,[t[21]||(t[21]=r('<h1 id="現代-linux-的五大初始化系統-1992-2015" tabindex="-1">現代 Linux 的五大初始化系統（1992-2015） <a class="header-anchor" href="#現代-linux-的五大初始化系統-1992-2015" aria-label="Permalink to “現代 Linux 的五大初始化系統（1992-2015）”">​</a></h1><p>在 Linux 和其他類 Uniux 系統中，init（初始化）進程是系統啓動時由內核執行的第一個進程，其進程 ID（PID）為 1，並靜默運行在後台，直到系統關閉。</p><p>init 進程負責啓動其他所有的進程，比如守護進程、服務和其他後台進程，因此，它是系統中其它所有進程之母（偏偏叫做“父進程”）。某個進程可以啓動許多個子進程，但在這個過程中，某個子進程的父進程結束之後，該子進程的父進程會變成 init 進程。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2016/08/Linux-init-Systems.png" alt=""></p><p>這麼多年過去了，許多的初始化系統在主流 Linux 脱穎而出，和本文中，我將你來看看在 Linux 操作系統最好的初始化系統。</p><h3 id="_1-system-v-init" tabindex="-1">1. System V Init <a class="header-anchor" href="#_1-system-v-init" aria-label="Permalink to “1. System V Init”">​</a></h3><p>System V (SysV) 是一個在類 Unix 系統中最為成熟而且大受歡迎的初始化方案，是 Unix/Linux 系統中所有進程的父進程。SysV 是第一個商業 Unix 系統設計的初始化方案。</p><p>除了 Gentoo 使用自主的初始化系統、Slackware 使用 BSD 風格的初始化方案外，幾乎所有的 Linux 發行版都率先使用 SysV 作為初始化方案。</p><p>隨着時間的推移，由於一些設計上的缺陷，有幾個 SysV 初始化替換方案已經開發出來，用以為 Linux 創建更加高效和完美的初始化系統。</p><p>儘管這些替代方案都超越了 SysV 並提供了更多新特性，但它們仍然和原始 SysV 初始化腳本保持兼容。</p><h3 id="_2-systemd" tabindex="-1">2. SystemD <a class="header-anchor" href="#_2-systemd" aria-label="Permalink to “2. SystemD”">​</a></h3><p>SystemD 是一個 Linux 平台中相對較新的初始化方案。它由 Fedora 15 引入，集成了各類工具以便更好的管理系統。主要目的是：系統初始化、管理和跟蹤引導進程中和系統運行時所有的系統進程。</p><p>Systemd 全面有別於其他傳統的 Unix 初始化系統，特別是在啓動系統和服務管理方面。它同樣兼容 SysV 和 LBS 初始化腳本。</p><p>其中較為突出的特性如下：</p><ul><li>純粹、簡單、高效的設計</li><li>啓動時的併發和並行處理</li><li>更好的 API</li><li>開啓可選進程的移除功能</li><li>使用 journald 來支持事件日誌</li><li>使用 systemd calender timers 來支持任務計劃</li><li>以二進制文件存儲日誌</li><li>保存 systemd 的狀態以待今後查看</li><li>與 GNOME 更好整合實現等</li></ul>',15)),n("p",null,[t[1]||(t[1]=i("查看 Systemd 初始化系統簡介：",-1)),s(l,{href:"https://fedoraproject.org/wiki/Systemd"},{default:e(()=>[...t[0]||(t[0]=[i("https://fedoraproject.org/wiki/Systemd",-1)])]),_:1})]),t[22]||(t[22]=r('<h3 id="_3-upstart" tabindex="-1">3. Upstart <a class="header-anchor" href="#_3-upstart" aria-label="Permalink to “3. Upstart”">​</a></h3><p>Upstart 是一個基於事件的初始化系統，由 Ubuntu 的製作團隊開發的，用以替代 SysV。它可以啓動不同的系統任務和進程、在系統運行時校驗進程並在系統關閉時結束進程。</p><p>它是一個使用 SysV 和 Systemd 啓動腳本的混合初始化系統，Upstart 中值得一提的特性如下：</p><ul><li>Ubuntu 的原生初始化系統，但可以運行在其他所有的發行版中</li><li>基於事件啓動/結束的任務和服務</li><li>啓動/結束任務和服務時生成事件</li><li>可以由其他系統進程發送事件</li><li>使用 D-Bus 和 init 進程通信</li><li>用户可以啓動/結束其各自的進程</li><li>可以再現崩潰的進程等</li></ul>',4)),n("p",null,[t[3]||(t[3]=i("訪問 Upstart 主頁：",-1)),s(l,{href:"http://upstart.ubuntu.com/index.html"},{default:e(()=>[...t[2]||(t[2]=[i("http://upstart.ubuntu.com/index.html",-1)])]),_:1})]),t[23]||(t[23]=r('<h3 id="_4-openrc" tabindex="-1">4. OpenRC <a class="header-anchor" href="#_4-openrc" aria-label="Permalink to “4. OpenRC”">​</a></h3><p>OpenRC 是一個基於依賴關係的類 Unix 系統初始化方案，兼容 SysV。基本可以説是 SysV 的升級版，但必須要清楚記住的是：OpenRC 並非只是完全替代 /sbin/init 文件。</p><p>它所提供的出色特性如下：</p><ul><li>可運行在包括 Gentoo 和 BSD 在內的多數 Linux 系統之中</li><li>支持硬件觸發的初始化腳本（LCTT 譯註：如硬件熱插拔所觸發的）</li><li>支持單個配置文件</li><li>不支持單個服務配置文件</li><li>以守護進程的方式運行</li><li>並行服務啓動等</li></ul>',4)),n("p",null,[t[5]||(t[5]=i("訪問 OpenRC 主頁：",-1)),s(l,{href:"https://wiki.gentoo.org/wiki/OpenRC"},{default:e(()=>[...t[4]||(t[4]=[i("https://wiki.gentoo.org/wiki/OpenRC",-1)])]),_:1})]),t[24]||(t[24]=r('<h3 id="_5-runit" tabindex="-1">5. runit <a class="header-anchor" href="#_5-runit" aria-label="Permalink to “5. runit”">​</a></h3><p>runit 同樣是一個跨平台初始化系統，可以運行在 GNU/Linux、Solaris、BSD 和 Mac OS X 中，用替代 SysV，同時提供服務監控。</p><p>相比於 SysV 和其他 Linux 初始化系統，它提供了一些好用和卓越的組件，如下：</p><ul><li>服務監控：每個服務都關聯一個服務目錄</li><li>清理進程狀態，以保證每個進程處於乾淨狀態</li><li>可靠的日誌機制</li><li>快速的系統啓動和關閉</li><li>可移植</li><li>打包方便</li><li>代碼體積小等</li></ul>',4)),n("p",null,[t[7]||(t[7]=i("訪問 runit 主頁：",-1)),s(l,{href:"http://smarden.org/runit/"},{default:e(()=>[...t[6]||(t[6]=[i("http://smarden.org/runit/",-1)])]),_:1})]),t[25]||(t[25]=n("p",null,"正如我之前所説的，Linux 中的初始化系統負責啓動和管理所有的進程。此外，SysV 是 Linux 系統中主要的初始化系統，但由於一些性能缺陷，系統開發者已經開發出幾個替代品。",-1)),t[26]||(t[26]=n("p",null,"在這裏，我已經介紹了幾個可用的替代方案，但你可能覺得有一些其他的初始化系統值得在此提及。請在下方的評論區將你的想法告訴我們。",-1)),t[27]||(t[27]=n("hr",null,null,-1)),n("p",null,[t[9]||(t[9]=i("via: ",-1)),s(l,{href:"http://www.tecmint.com/best-linux-init-systems/"},{default:e(()=>[...t[8]||(t[8]=[i("http://www.tecmint.com/best-linux-init-systems/",-1)])]),_:1})]),n("p",null,[t[13]||(t[13]=i("作者：",-1)),s(l,{href:"http://www.tecmint.com/author/aaronkili/"},{default:e(()=>[...t[10]||(t[10]=[i("Aaron Kili",-1)])]),_:1}),t[14]||(t[14]=i(" 譯者：",-1)),s(l,{href:"https://github.com/GHLandy"},{default:e(()=>[...t[11]||(t[11]=[i("GHLandy",-1)])]),_:1}),t[15]||(t[15]=i(" 校對：",-1)),s(l,{href:"https://github.com/wxy"},{default:e(()=>[...t[12]||(t[12]=[i("wxy",-1)])]),_:1})]),n("p",null,[t[18]||(t[18]=i("本文由 ",-1)),s(l,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[16]||(t[16]=[i("LCTT",-1)])]),_:1}),t[19]||(t[19]=i(" 原創編譯，",-1)),s(l,{href:"https://linux.cn/"},{default:e(()=>[...t[17]||(t[17]=[i("Linux中國",-1)])]),_:1}),t[20]||(t[20]=i(" 榮譽推出",-1))])])}const V=p(m,[["render",d]]);export{C as __pageData,V as default};
